export const examples: ReadonlyArray<SiteExample> = [
  { slug: "mcp-server", title: "Build an MCP server", group: "AI", summary: "The Model Context Protocol is how AI assistants call tools you host. A Worker is a good place for an MCP server: public, fast, cheap. Effect's `McpServer` serves tools defined with Schemas over MCP's HTTP transport, as routes on the Worker's `HttpRouter`. Parameters are decoded and results encoded by the Schemas, so a model gets typed errors instead of crashes.", handler: example_mcp_server, vars: {} },
  { slug: "anthropic-chat", title: "Connect to Claude with Effect AI", group: "AI", summary: "`effect/ai` gives every provider the same interface: a `LanguageModel` service you call from your code, and a provider layer you choose once. Here the provider is Anthropic, running on the Worker's own `fetch`, with the API key read as a redacted secret. (The check runs against a stand-in for the API; deploy with a real `ANTHROPIC_API_KEY` secret to talk to Claude.)", handler: undefined, vars: {} },
  { slug: "timeout-any-effect", title: "Add a timeout to any effect", group: "Basics", summary: "A promise has no built-in time limit. Every effect does: `Effect.timeout` fails with a `TimeoutError` when the time runs out, and interrupts the work that was too slow, so nothing keeps running in the background.", handler: example_timeout_any_effect, vars: {} },
  { slug: "cancel-with-interruption", title: "Cancel async work with interruption", group: "Basics", summary: "Deno cancels work with an `AbortController` passed down by hand. In Effect, cancellation is interruption: any running effect can be interrupted, and its finalizers run, without threading a signal through every call. An `AbortSignal` from outside can still trigger it.", handler: example_cancel_with_interruption, vars: {} },
  { slug: "deep-equal", title: "Check if two values are deeply equal", group: "Basics", summary: "Two objects with the same contents are not equal with `===`. Effect's `Equal.equals` compares structurally: plain objects, arrays, Maps, Sets and Dates by value, and Effect data types (Data classes, Option, HashMap, ...) by their own equality.", handler: example_deep_equal, vars: {} },
  { slug: "exponential-backoff", title: "Exponential backoff", group: "Basics", summary: "Exponential backoff retries a failing operation with growing delays, so a struggling service gets room to recover. In Effect the policy is a `Schedule`, and `Effect.retry` applies it. Errors are typed, so the policy can decide which ones are worth retrying.", handler: example_exponential_backoff, vars: {} },
  { slug: "seeded-random", title: "Generate seeded random numbers", group: "Basics", summary: "`Math.random` cannot be seeded, so tests that depend on it are flaky. Effect reads randomness from the `Random` service: run the same code with `Random.withSeed` and it produces the same numbers every time.", handler: example_seeded_random, vars: {} },
  { slug: "hello-world", title: "Hello World", group: "Basics", summary: "The smallest Worker you can write with Effect: a fetch handler that returns a response. Where Deno has `Deno.serve`, a Worker exports its handlers, and `Worker.make` builds that export from Effects.", handler: example_hello_world, vars: {} },
  { slug: "memoize", title: "Memoize an expensive function", group: "Basics", summary: "Memoization caches the result of a call so repeated calls are free. Effect's `Cache` memoizes an effectful lookup with a capacity and a time to live, and concurrent lookups of the same key share one computation.", handler: example_memoize, vars: {} },
  { slug: "concurrency-limit", title: "Run tasks with a concurrency limit", group: "Basics", summary: "Firing hundreds of requests at once can overload a service or hit a rate limit. `Effect.forEach` takes a `concurrency` option, and a `Semaphore` limits concurrency across unrelated parts of a program.", handler: example_concurrency_limit, vars: {} },
  { slug: "repeat-with-schedules", title: "Set timeouts and intervals with schedules", group: "Basics", summary: "Where a Deno script reaches for `setTimeout` and `setInterval`, Effect uses schedules: values that describe when to run something again. They compose, they stop on their own, and they work with the test clock.", handler: example_repeat_with_schedules, vars: {} },
  { slug: "sleep-and-delay", title: "Sleep and delay execution", group: "Basics", summary: "Programs often need to wait: between retries, while polling, or to pace requests. In Effect a sleep is just another effect: it never blocks, it reads time from the `Clock` (so tests can fast-forward it), and it can be interrupted.", handler: example_sleep_and_delay, vars: {} },
  { slug: "cache-api", title: "Cache responses with the Cache API", group: "Cloudflare runtime", summary: "Deno implements the Web Cache API; Workers have it too, as `caches.default`, in front of every data center. `Cache.cached` serves a request from the cache or runs the effect, returns its response and stores a copy in the background with `ctx.waitUntil`, so the user never waits for the write.", handler: undefined, vars: {} },
  { slug: "cron", title: "Cron Triggers", group: "Cloudflare runtime", summary: "`Deno.cron` registers a function to run on a schedule. On Workers the schedules live in the Worker's configuration (`triggers.crons`) and every trigger calls the `scheduled` handler. `Scheduled.dispatch` routes each trigger to the effect registered for its expression, and checks the expressions with Effect's `Cron` parser when the Worker loads.", handler: undefined, vars: {} },
  { slug: "d1-sql", title: "D1: SQL with Effect", group: "Cloudflare runtime", summary: "The Deno examples use SQLite through `node:sqlite`; a Worker has D1, a SQLite database as a binding. `@effect/sql-d1` makes it an Effect `SqlClient`: queries are tagged templates with parameters bound safely, and rows are decoded with a Schema.", handler: undefined, vars: {} },
  { slug: "durable-object-counter", title: "Durable Objects: a consistent counter", group: "Cloudflare runtime", summary: "A Durable Object is a single instance with its own storage: every request for the same name reaches the same object, one at a time, so a counter never loses an update. `DurableObject.makeRunner` runs Effects inside the object with its storage as Effect's `KeyValueStore`.", handler: undefined, vars: {} },
  { slug: "environment-variables", title: "Environment variables and secrets", group: "Cloudflare runtime", summary: "Deno reads configuration with `Deno.env.get`. A Worker gets vars and secrets as bindings, and `Worker.make` exposes the string ones to Effect's `Config`: typed (numbers, booleans, durations), with defaults, and with `Config.Redacted` for secrets so they never end up in a log line.", handler: example_environment_variables, vars: {"APP_NAME":"flareosaur","MAX_ITEMS":"25","API_TOKEN":"s3cr3t-token"} },
  { slug: "queues", title: "Queues: offload work to a consumer", group: "Cloudflare runtime", summary: "Deno Queues let an app hand work to a background listener. On Workers the same thing is a Queue with a producer binding and a `queue` handler. With `Queue.Producer` and `Queue.consume`, messages are Schema-typed on both ends: a message that does not decode is logged and dropped instead of crashing the consumer or retrying forever.", handler: undefined, vars: {} },
  { slug: "r2-files", title: "R2: reading and writing files", group: "Cloudflare runtime", summary: "A Worker has no disk; files go to an R2 bucket. The `R2.Bucket` service covers what the Deno examples do with `Deno.readFile`, `Deno.writeFile`, `Deno.remove` and walking a directory, with typed errors and `Option` for missing files. Object bodies are Effect `Stream`s, so large files never have to fit in memory.", handler: undefined, vars: {} },
  { slug: "websocket-chat", title: "WebSocket chat with Durable Objects", group: "Cloudflare runtime", summary: "A chat room needs one place that knows every connected socket. Each room is a Durable Object: the Worker forwards the WebSocket upgrade to the room's object, which accepts the socket with the hibernation API and broadcasts every message to the sockets of that room. The room keeps its last messages in storage, so new visitors can read the history.", handler: undefined, vars: {} },
  { slug: "kv", title: "Workers KV: key/value storage", group: "Cloudflare runtime", summary: "Deno has Deno KV built in; a Worker gets Workers KV through a binding. `Kv.layer` provides it as Effect's `KeyValueStore`, so a Schema-validated store is one call away: values are checked when they are written and when they are read back.", handler: undefined, vars: {} },
  { slug: "aes-encryption", title: "AES encryption and decryption", group: "Cryptography", summary: "AES-GCM encrypts and authenticates in one step: a ciphertext that was changed fails to decrypt. The helpers generate a fresh nonce from the Effect `Crypto` service for every message and put it in front of the ciphertext, so the nonce never has to be stored separately.", handler: example_aes_encryption, vars: {} },
  { slug: "uuids-and-ulids", title: "Generate and validate UUIDs and ULIDs", group: "Cryptography", summary: "UUID v4 is random, v7 starts with a timestamp so new ids sort last, and v5 is the same for the same name every time. ULIDs are sortable too, in a shorter alphabet. Generation reads time and randomness from Effect services (`Clock`, `Crypto`), so tests can pin both.", handler: example_uuids_and_ulids, vars: {} },
  { slug: "hashing", title: "Hashing", group: "Cryptography", summary: "Web Crypto covers the SHA family. `@mikepage/flareosaur/crypto` adds the rest of std's algorithms (BLAKE3, SHA-3, Keccak, MD5, FNV, ...), running as WebAssembly that Workers load as a module, and `digestStream` hashes a `Stream` chunk by chunk, so a large R2 object never has to be in memory.", handler: example_hashing, vars: {} },
  { slug: "password-hashing", title: "Hashing and verifying passwords", group: "Cryptography", summary: "Passwords must never be stored in plain text, or hashed with a fast hash. PBKDF2 (available in Web Crypto on Workers) stretches a password with a random salt and many iterations. Store the salt and iteration count with the hash, and compare in constant time when a user logs in.", handler: example_password_hashing, vars: {} },
  { slug: "webhook-signatures", title: "HTTP server: verifying webhook signatures", group: "Cryptography", summary: "Webhook senders sign each delivery with a shared secret so the receiver can reject forgeries. Verify the HMAC of the raw body before parsing it, with a constant-time comparison, and keep the secret in `Config.Redacted`.", handler: example_webhook_signatures, vars: {"WEBHOOK_SECRET":"whsec_test_secret"} },
  { slug: "dns-discovery", title: "DNS discovery: scan a domain in one shot", group: "DNS & domains", summary: "Find a domain's apex records, its email-authentication and Microsoft 365 setup, and its subdomains, with about a hundred DNS-over-HTTPS probes run twenty at a time with `Effect.forEach`. Names seen on certificates in Certificate Transparency logs (crt.sh) are probed too; that lookup has a timeout and one retry, is cached for an hour with `@mikepage/flareosaur/workers/cache`, and degrades to a note when crt.sh is down instead of failing the scan.", handler: example_dns_discovery, vars: {} },
  { slug: "dns-lookup", title: "DNS lookup over DNS-over-HTTPS", group: "DNS & domains", summary: "Query one DNS record type for a name over DNS-over-HTTPS, from Cloudflare's 1.1.1.1 resolvers or Google's. The query string is decoded with a Schema, the resolver's JSON answer is fetched with `HttpClient` under a timeout and decoded with a Schema too, and a failing resolver is a typed error that becomes a 502.", handler: example_dns_lookup, vars: {} },
  { slug: "rdap-lookup", title: "RDAP domain lookup", group: "DNS & domains", summary: "Looks up a domain's registration data over RDAP, the structured successor to WHOIS: registrar, status, key dates, nameservers and DNSSEC. The RDAP server comes from a bundled copy of the IANA bootstrap registry. The request goes through `HttpClient` with a retry for dropped connections and a timeout, and the registry's answer is decoded with a lenient Schema; every upstream problem is one typed `RdapError`, answered with a 502.", handler: example_rdap_lookup, vars: {} },
  { slug: "dmarc-validator", title: "DMARC validator", group: "Email", summary: "Fetches a domain's `_dmarc` TXT record over DNS-over-HTTPS and checks the policy for common mistakes, with a description of every tag. The query is a Schema that cleans what people paste (`https://_dmarc.Example.com/`) and rejects anything that is not a domain; the DoH answer is fetched with `HttpClient`, bounded by `Effect.timeout` and decoded with a Schema.", handler: example_dmarc_validator, vars: {} },
  { slug: "smtp-submission-test", title: "SMTP submission test", group: "Email", summary: "Tests a mail server's submission port over raw TCP: reads the banner, sends EHLO, upgrades with STARTTLS when offered (implicit TLS on 465), sends EHLO again and returns the capabilities plus the full transcript. The socket from `cloudflare:sockets` is an Effect resource (`acquireRelease`), every read has a timeout, and protocol failures are typed errors; the host is checked over DNS-over-HTTPS with `HttpClient` so only public addresses are dialled.", handler: example_smtp_submission_test, vars: {} },
  { slug: "spf-validator", title: "SPF validator", group: "Email", summary: "Resolves a domain's SPF record over DNS-over-HTTPS, parses every term and walks each `include` and `redirect` into a tree, counting DNS lookups against RFC 7208's limit of 10 and flagging common mistakes. The walk is a recursive Effect: the lookup count lives in a `Ref`, each TXT query is an `HttpClient` call bounded by `Effect.timeout`, and a failed lookup becomes a note on its node instead of failing the whole request. Pass `record` to check a draft record before you publish it.", handler: example_spf_validator, vars: {} },
  { slug: "compress-decompress", title: "Compress and decompress data", group: "Encoding", summary: "Workers implement `CompressionStream` and `DecompressionStream`. Wrapped as Effect `Stream` steps, compression is one more stage in a pipeline, whether the data is a string in memory or a large R2 object.", handler: example_compress_decompress, vars: {} },
  { slug: "front-matter", title: "Extract front matter from Markdown", group: "Encoding", summary: "Front matter is a metadata block at the top of a Markdown file, in YAML, TOML or JSON. `extract` finds the format, parses the block and returns the rest of the document; with a Schema the attributes come out typed.", handler: example_front_matter, vars: {} },
  { slug: "hex-base64-encoding", title: "Hex, base64, base32 and base58 encoding", group: "Encoding", summary: "Binary data often has to travel as text: in URLs, JSON or headers. Effect ships hex and base64; flareosaur adds std's base32, base58 and ascii85 with the same shape. Encoding cannot fail; decoding returns a `Result`, so bad input is a value to handle, not an exception.", handler: example_hex_base64_encoding, vars: {} },
  { slug: "csv", title: "Parse and serialize CSV, also as streams", group: "Encoding", summary: "CSV is still how data moves between spreadsheets and systems. A Schema codec decodes CSV with a header row into typed records, numbers included, and `parseStream` handles files too big for memory one row at a time, whatever the chunk boundaries are.", handler: example_csv, vars: {} },
  { slug: "toml-yaml-config", title: "Parse and serialize TOML and YAML", group: "Encoding", summary: "Configuration files map to typed values with a Schema codec: TOML or YAML text in, a validated config object out, and back again. Both parsers are std's complete implementations (the full TOML spec, YAML 1.2 with multiple documents and tags), behind typed errors.", handler: example_toml_yaml_config, vars: {} },
  { slug: "json-lines", title: "Stream JSON Lines data", group: "Encoding", summary: "JSON Lines (NDJSON) puts one JSON value per line, so a reader can process records as they arrive. Request and response bodies are Effect streams: parse an upload line by line, and produce a download one record at a time, without holding either in memory.", handler: example_json_lines, vars: {} },
  { slug: "http-requests", title: "HTTP requests", group: "HTTP", summary: "Effect's `HttpClient` wraps `fetch` with typed errors, Schema-decoded responses, retries and timeouts. On Workers it runs on the runtime's own `fetch` through `FetchHttpClient.layer`.", handler: undefined, vars: {} },
  { slug: "http-server-basic-auth", title: "HTTP server: basic authentication", group: "HTTP", summary: "Basic authentication sends a username and password with every request. The password is a secret, so it comes from `Config.Redacted`, and the comparison takes the same time whatever the input, so the response time leaks nothing about the password.", handler: example_http_server_basic_auth, vars: {"ADMIN_PASSWORD":"correct-horse"} },
  { slug: "http-server-etag", title: "HTTP server: caching headers and ETags", group: "HTTP", summary: "Cache headers let clients skip downloads they already have. An ETag is a fingerprint of the response: the client sends it back in `If-None-Match`, and if nothing changed the server answers `304 Not Modified` with no body. `Cache-Control` says how long a copy may be reused without asking.", handler: example_http_server_etag, vars: {} },
  { slug: "http-server-negotiation", title: "HTTP server: content negotiation", group: "HTTP", summary: "One URL can serve JSON to scripts and HTML to browsers, in the reader's language. Negotiation reads the `Accept` and `Accept-Language` headers, weighs their q-values, and picks the best of what the server offers; an `Option` says when nothing fits.", handler: example_http_server_negotiation, vars: {} },
  { slug: "http-server-cookies", title: "HTTP server: cookies", group: "HTTP", summary: "Cookies carry state between requests. Read them from the request with a Schema (so a tampered value is rejected), and set or expire them on the response; Effect checks names, values and options when it serializes them.", handler: example_http_server_cookies, vars: {} },
  { slug: "http-server-cors", title: "HTTP server: CORS", group: "HTTP", summary: "Browsers block cross-origin requests unless the server opts in. Add `HttpRouter.cors` to the routes and the router answers preflight requests and adds the CORS headers to every response.", handler: example_http_server_cors, vars: {} },
  { slug: "http-server-problem-details", title: "HTTP server: errors as problem details", group: "HTTP", summary: "APIs should report errors in a format clients can rely on. RFC 9457 problem details are JSON with `type`, `title`, `status` and `detail`. Fail a handler with a `Problem`, a typed error like any other, and the router turns it into an `application/problem+json` response.", handler: example_http_server_problem_details, vars: {} },
  { slug: "http-server-health-checks", title: "HTTP server: health checks", group: "HTTP", summary: "A liveness endpoint answers as long as the Worker runs; a readiness endpoint checks the dependencies. The checks run concurrently, each with a timeout, and a failing check is reported instead of failing the endpoint.", handler: undefined, vars: {} },
  { slug: "http-server-pagination", title: "HTTP server: paginating results", group: "HTTP", summary: "APIs that return lists need pagination. Query parameters are decoded with a Schema (with defaults and limits), and the cursor is opaque to the client: a base64url offset it hands back to get the next page.", handler: example_http_server_pagination, vars: {} },
  { slug: "http-server-rate-limit", title: "HTTP server: rate limiting", group: "HTTP", summary: "A rate limiter protects a server from clients that send too many requests. A Worker runs in many isolates at once, so in-memory counters would each see only part of the traffic. Give every client its own Durable Object instead: one instance per IP address sees all of that client's requests, and runs Effect's `RateLimiter` with an in-memory store.", handler: undefined, vars: {} },
  { slug: "http-server-request-timeouts", title: "HTTP server: request timeouts", group: "HTTP", summary: "A handler that waits on a slow upstream can hold a request open far too long. Give the handler a budget with `Effect.timeout`: when it runs out the work is interrupted, not left running, and the client gets a 504.", handler: example_http_server_request_timeouts, vars: {} },
  { slug: "http-server-routing", title: "HTTP server: routing", group: "HTTP", summary: "`HttpRouter` maps methods and paths to handlers. Path parameters are decoded with a Schema, so `/books/abc` is rejected before the handler runs. `Worker.make` serves the router as the Worker's fetch handler.", handler: example_http_server_routing, vars: {} },
  { slug: "http-server-sse", title: "HTTP server: server-sent events", group: "HTTP", summary: "Server-sent events push updates from the server over one long-lived response. The events are an Effect `Stream`, and `Sse.encode` turns it into the `text/event-stream` wire format, so the producer is ordinary stream code: here, a tick every 10ms, three times, then a final event.", handler: example_http_server_sse, vars: {} },
  { slug: "http-server-signed-cookies", title: "HTTP server: sessions with signed cookies", group: "HTTP", summary: "A session cookie must not be editable by the client, or anyone could claim to be anyone. A signed cookie carries an HMAC of its value: the server verifies it on every request and treats a tampered cookie as no cookie at all. The signing key comes from a secret, through `Config`.", handler: example_http_server_signed_cookies, vars: {"COOKIE_SECRET":"change-me-to-a-long-random-string"} },
  { slug: "http-server-streaming", title: "HTTP server: streaming responses", group: "HTTP", summary: "A response body can be an Effect `Stream`: bytes go out as they are produced, so the Worker never holds the whole body in memory. Request bodies are streams too, which makes a streaming transform a pipeline.", handler: example_http_server_streaming, vars: {} },
  { slug: "http-server-validate-json", title: "HTTP server: validate JSON bodies", group: "HTTP", summary: "Never trust a request body. `HttpServerRequest.schemaBodyJson` parses the body and decodes it with a Schema in one step; a body that does not match fails with a `SchemaError` that says exactly what is wrong.", handler: example_http_server_validate_json, vars: {} },
  { slug: "websocket-echo", title: "HTTP server: WebSockets", group: "HTTP", summary: "A Worker answers a WebSocket upgrade with one end of a `WebSocketPair` and keeps the other. Turning the socket's messages into an Effect `Stream` makes the handler a pipeline: here every message is echoed back. For state shared between sockets, see the chat example with Durable Objects.", handler: example_websocket_echo, vars: {} },
  { slug: "browserinfo", title: "Browser info", group: "Network", summary: "What this Worker sees of your connection: the request headers, the User-Agent Client Hints (asked for with `Accept-CH`), Cloudflare's `request.cf` (country, city, colo, ASN, TLS, HTTP protocol) and your IP with its PTR record. The PTR lookup is DNS over HTTPS through `HttpClient`, with a timeout, a Schema-decoded answer and a typed error.", handler: example_browserinfo, vars: {} },
  { slug: "cloudflare-edge", title: "Cloudflare edge", group: "Network", summary: "Which Cloudflare data center is serving you, where it is, and how far it is from you. The colo code and your location come free on `request.cf` (decoded with a Schema, and optional outside the edge); the colo's city and country come from a bundled JSON list of data centers.", handler: example_cloudflare_edge, vars: {} },
  { slug: "ip-info", title: "IP info", group: "Network", summary: "Your IP address and where it is (city, country, timezone, network) as a CORS-enabled JSON endpoint that replaces ipinfo.io and ip-api. A Worker gets all of this for free on `request.cf`; the example decodes that untrusted object with a Schema into `Option`s, since `cf` and `CF-Connecting-IP` are missing outside Cloudflare's edge.", handler: example_ip_info, vars: {} },
  { slug: "ipv6-utils", title: "IPv6 utils", group: "Network", summary: "Expands and compresses IPv6 addresses, works out the network, first and last address and size for a prefix length, and checks whether an address is inside a CIDR range. The math is pure 128-bit `BigInt` code using `Option` and `Result`; the query string is decoded with a Schema, and `use=mine` reads the caller's address from `CF-Connecting-IP`.", handler: example_ipv6_utils, vars: {} },
  { slug: "structured-logging", title: "Structured logging", group: "Observability", summary: "Workers Logs index JSON log lines, so structured logs are searchable by field. Effect's logger writes one JSON object per line when the layer swaps in `Logger.consoleJson`; annotations and spans become fields, so every line of a request carries its request id without passing it around.", handler: example_structured_logging, vars: {} },
  { slug: "escape-html", title: "Escape HTML, CSS and JavaScript", group: "Standard library", summary: "Putting user input into HTML without escaping it opens the door to cross-site scripting. `safeHtml` is a template tag that escapes every interpolated value, so the safe way is also the short way.", handler: example_escape_html, vars: {} },
  { slug: "semver-versions", title: "Parse and compare semver versions", group: "Standard library", summary: "Version strings cannot be compared as text: \"1.10.0\" sorts before \"1.2.0\". A parsed `SemVer` comes with an Effect `Order`, so arrays sort correctly with `Array.sort`, and ranges, increments and comparisons follow the semver spec. Parsing returns a `Result` instead of throwing.", handler: example_semver_versions, vars: {} },
  { slug: "dates", title: "Parse, format and compute with dates", group: "Standard library", summary: "Effect's `DateTime` is an immutable instant (optionally with a time zone) and reads \"now\" from the `Clock`, so code that uses the current time stays testable. `@mikepage/flareosaur/datetime` adds std's pattern-based `format` and `parse`, and calendar helpers.", handler: example_dates, vars: {} },
  { slug: "path-operations", title: "Path operations", group: "Standard library", summary: "Object keys in R2, routes and asset manifests are all paths, even on a runtime without a filesystem. The path module has std's POSIX and Windows implementations as pure functions and as layers for Effect's `Path` service. On Workers there is no working directory, so relative paths resolve against `/`.", handler: example_path_operations, vars: {} },
  { slug: "dotenv-config", title: "Read configuration from .env text", group: "Standard library", summary: "Workers have no filesystem to load a `.env` file from, but .env text can still be a config source: bundled with the Worker, stored in KV, or kept in a test. `Dotenv.layer` turns it into an Effect `ConfigProvider`, with std's variable expansion (`${BASE}/v2`), so `Config` reads from it.", handler: example_dotenv_config, vars: {} },
  { slug: "read-lines", title: "Read a stream line by line", group: "Streams", summary: "Command line tools read input line by line; a Worker does the same with a request body or an R2 object. `toLines` decodes bytes and splits lines across chunk boundaries, and the rest is ordinary stream code: filter, take, count, without buffering the whole input.", handler: example_read_lines, vars: {} },
  { slug: "external-link-scanner", title: "External link scanner", group: "Web", summary: "Crawls a website (pages on the same registrable domain, up to 100) and lists every external link, script, iframe and form target, grouped by destination domain. Domains that look like injected spam are flagged: nonstandard TLDs, raw IPs, punycode hosts, spam keywords, and active content from a flagged domain. Pages are fetched with `HttpClient` and a per-request timeout, a breadth-first level at a time with `Effect.forEach({ concurrency })`, and the crawl is capped so one request stays within the Worker's subrequest budget.", handler: example_external_link_scanner, vars: {} },
  { slug: "intl-tel-validate", title: "Phone number validator", group: "Web", summary: "Validates an international phone number: is it valid, which country and type (mobile, fixed line, ...) is it, and what are its national, international and E.164 formats. An npm library (libphonenumber-js, with its full metadata) bundles straight into the Worker without `nodejs_compat`; Schema validates the query before the library sees it.", handler: example_intl_tel_validate, vars: {} },
  { slug: "url-pattern", title: "Parse URLs and match routes with URLPattern", group: "Web standard APIs", summary: "`URL` parses and edits URLs, and `URLPattern` (built into Workers) matches them against route patterns. Pattern groups are strings; decode them with a Schema to get typed values, and use `Option` for a match that may not happen.", handler: example_url_pattern, vars: {} },
]
